#include <iostream>
#include <vector>

void remove_even(std::vector<int>& values) {
    for (auto it = values.begin(); it != values.end();) {
        if (*it % 2 == 0) {
            it = values.erase(it);
        } else {
            ++it;
        }
    }
}

int main() {
    std::vector<int> values{1, 2, 3, 4};
    remove_even(values);
    std::cout << values.size() << '\n';
    values.reserve(16); // Capacity may change; no old observer is retained.
    std::cout << values.size() << '\n';
    std::cout << values.at(1) << '\n';
    values.push_back(5);
    for (const int value : values) {
        std::cout << value << '\n';
    }
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

struct Event {
    std::string label;
    int price;
};

bool cheaper(const Event& left, const Event& right) {
    return left.price < right.price;
}

std::vector<Event> sorted_snapshot(std::vector<Event> events) {
    std::stable_sort(events.begin(), events.end(), cheaper);
    return events;
}

int main() {
    const std::vector<Event> original{{"T1",20},{"T2",10},{"T1",10}};
    const auto sorted = sorted_snapshot(original);
    for (const auto& event : sorted) {
        std::cout << event.label << ':' << event.price << '\n';
    }
    std::cout << original.front().label << ':' << original.front().price << '\n';
    std::cout << sorted.size() << '\n';
}
